// Node 2A: Cào Comment TikTok từ Kênh @baothetindung.abf & Lọc Trùng
const apifyToken = process.env.APIFY_TOKEN || 'YOUR_APIFY_TOKEN';
const targetUrl = 'https://www.tiktok.com/@baothetindung.abf';
const limitPerPost = 50;

const staticData = $getWorkflowStaticData('global');
staticData.tiktokCommentCounts = staticData.tiktokCommentCounts || {};
staticData.seenCommentIds = staticData.seenCommentIds || [];

console.log(`🚀 [Node 2A - TikTok] Bắt đầu cào comment từ Kênh: ${targetUrl}`);

let posts = [];
try {
  posts = await helpers.httpRequest({
    method: 'POST',
    url: `https://api.apify.com/v2/acts/clockworks~free-tiktok-scraper/run-sync-get-dataset-items?token=${apifyToken}`,
    headers: { 'Content-Type': 'application/json' },
    body: {
      profiles: [targetUrl],
      resultsPerPage: 20,
      commentsPerPost: limitPerPost,
      shouldDownloadVideos: false,
      shouldDownloadCovers: false
    },
    json: true
  });
} catch (err) {
  console.error('❌ Lỗi gọi Apify TikTok Scraper:', err.message || err);
  posts = [];
}

if (!Array.isArray(posts)) posts = [];

const allTikTokComments = [];
const seenSet = new Set(staticData.seenCommentIds);

for (const post of posts) {
  const videoUrl = post.webVideoUrl || post.url || targetUrl;
  const videoId = String(post.id || videoUrl);
  const currentCommentCount = Number(post.commentCount || post.stats?.commentCount || 0);
  const lastCommentCount = staticData.tiktokCommentCounts[videoId] || 0;

  if (currentCommentCount > 0 && currentCommentCount <= lastCommentCount && !post.commentsDatasetUrl) {
    continue;
  }

  const commentsDatasetUrl = post.commentsDatasetUrl;

  if (commentsDatasetUrl) {
    try {
      const commentsData = await helpers.httpRequest({
        method: 'GET',
        url: commentsDatasetUrl,
        json: true
      });

      if (Array.isArray(commentsData)) {
        for (const c of commentsData) {
          const commentText = (c.text || c.content || c.commentText || '').trim();
          const commentId = String(c.id || c.cid || `${c.uniqueId}_${commentText}`);

          if (commentText.length > 0 && !seenSet.has(commentId)) {
            seenSet.add(commentId);
            allTikTokComments.push({
              platform: 'tiktok',
              group_or_page: 'baothetindung.abf',
              author: String(c.uniqueId || c.nickname || c.author || 'TikTok_User').substring(0, 100),
              content: commentText,
              comment_created_at: c.createTimeISO || c.createdAt || (c.createTime ? new Date(c.createTime * 1000).toISOString() : new Date().toISOString()),
              source_url: videoUrl,
              status: 'pending'
            });
          }
        }
      }
    } catch (e) {
      console.error(`⚠️ Lỗi tải commentsDatasetUrl cho bài ${videoUrl}:`, e.message || e);
    }
  } else if (post.text && post.text.trim().length > 0) {
    const textId = `post_${videoId}_${post.text.trim().substring(0, 30)}`;
    if (!seenSet.has(textId)) {
      seenSet.add(textId);
      allTikTokComments.push({
        platform: 'tiktok',
        group_or_page: 'baothetindung.abf',
        author: String(post.authorMeta?.nickName || post.authorMeta?.name || 'baothetindung.abf').substring(0, 100),
        content: post.text.trim(),
        comment_created_at: post.createTimeISO || new Date().toISOString(),
        source_url: videoUrl,
        status: 'pending'
      });
    }
  }

  staticData.tiktokCommentCounts[videoId] = Math.max(currentCommentCount, lastCommentCount);
}

staticData.seenCommentIds = Array.from(seenSet).slice(-2000);

console.log(`✅ [Node 2A - TikTok] Đã tìm thấy ${allTikTokComments.length} comment TikTok MỚI!`);
return allTikTokComments.map(item => ({ json: item }));

// NHÁNH 3B: Gom TOÀN BỘ comment & tin nhắn Zalo/TikTok từ Supabase -> Xây dựng Prompt phân tích chi tiết & Định hướng Giám Đốc
const allComments = $input.all().map((item, index) => ({
  id: item.json.id,
  index: index + 1,
  platform: item.json.platform || 'social',
  group_or_page: item.json.group_or_page || '',
  author: item.json.author || 'User',
  content: item.json.content
})).filter(c => c.content && String(c.content).trim().length > 0);

if (allComments.length === 0) {
  return [];
}

const promptText = `Bạn là chuyên gia phân tích dữ liệu nhu cầu thẻ tín dụng và cố vấn chiến lược tài chính người dùng cho Ban Giám Đốc ABF.

Dưới đây là danh sách comment/tin nhắn thu thập từ Database (TikTok & Nhóm Zalo Bào Thẻ Thông Minh). Hãy phân tích kỹ từng comment/tin nhắn và trả về ĐÚNG 1 mảng JSON chuẩn (không chứa bất kỳ markdown, lời chào hay text nào ngoài mảng JSON) theo định dạng:
[
  {
    "index": 1,
    "spending_category": "du_lich|mua_sam_online|tra_gop|rut_tien|an_uong|sang_ngang_the|hoan_tien|khac",
    "target_bank": "Tên ngân hàng cụ thể khách hàng đang quan tâm hoặc sở hữu (ví dụ: VIB, VPBank, Techcombank, TPBank, Sacombank, HSBC, MB,...) hoặc 'Chưa xác định'",
    "target_card": "Tên dòng thẻ tín dụng cụ thể (ví dụ: Max Card, StepUp, Travel Élite, Cash Back, Live+, Signature, Platinum,...) hoặc 'Chưa xác định'",
    "intent": "hoi_dieu_kien_mo_the|hoi_uu_dai|so_sanh_the|ho_tro_sang_ngang|tu_van_tra_gop_rut_tien|khac",
    "summary": "Tóm tắt 1-2 câu: Khách hàng đang cần gì, thuộc lĩnh vực chi tiêu nào, quan tâm dòng thẻ hay ngân hàng nào cụ thể.",
    "director_action": "1-2 câu đưa ra định hướng chiến lược & hành động đề xuất cho Ban Giám Đốc ABF (ví dụ: Đề xuất Ban Giám Đốc đẩy mạnh chương trình tư vấn sang ngang thẻ VIB Max Card và tiếp cận nhóm khách hàng có nhu cầu hoàn tiền học phí/mua sắm)."
  }
]

Yêu cầu phân tích chặt chẽ:
1. 'spending_category': Phân loại chính xác lĩnh vực chi tiêu trọng tâm.
2. 'target_bank': Nhận diện đúng tên ngân hàng được đề cập.
3. 'target_card': Nhận diện đúng tên dòng thẻ tín dụng.
4. 'intent': Xác định động cơ chính của khách hàng.
5. 'summary': Tóm tắt súc tích nhu cầu thực tế của khách.
6. 'director_action': Đưa ra giải pháp/hành động kinh doanh giá trị cao cho Ban Giám Đốc để tối ưu tỷ lệ chuyển đổi mở thẻ.

Danh sách comment/tin nhắn cần phân tích:
${JSON.stringify(allComments, null, 2)}`;

const payloadObj = {
  contents: [
    {
      parts: [
        { text: promptText }
      ]
    }
  ],
  generationConfig: {
    responseMimeType: "application/json"
  }
};

return [{
  json: {
    total_count: allComments.length,
    comment_ids: allComments.map(c => c.id).filter(Boolean),
    gemini_payload_str: JSON.stringify(payloadObj)
  }
}];

// Unpack mảng kết quả JSON từ Gemini với cơ chế 2 lớp (JSON.parse + Regex Object Fallback)
const jsonInput = $input.first()?.json || {};

let rawText = '';
if (typeof jsonInput === 'string') {
  rawText = jsonInput;
} else if (jsonInput?.content?.parts?.[0]?.text) {
  rawText = jsonInput.content.parts[0].text;
} else if (jsonInput?.text) {
  rawText = jsonInput.text;
} else if (jsonInput?.candidates?.[0]?.content?.parts?.[0]?.text) {
  rawText = jsonInput.candidates[0].content.parts[0].text;
} else {
  rawText = JSON.stringify(jsonInput);
}

// Xóa markdown ```json nếu có
rawText = rawText.replace(/```json/gi, '').replace(/```/gi, '').trim();

let aiArray = [];

// LỚP 1: Thử parse toàn bộ mảng JSON chuẩn
try {
  const firstB = rawText.indexOf('[');
  const lastB = rawText.lastIndexOf(']');
  if (firstB !== -1 && lastB !== -1 && lastB > firstB) {
    aiArray = JSON.parse(rawText.substring(firstB, lastB + 1));
  }
} catch (e1) {}

// LỚP 2: Nếu lớp 1 thất bại (do ký tự escape, dấu phẩy thừa hoặc bị cắt đuôi), dùng Regex bóc tách từng object
if (!Array.isArray(aiArray) || aiArray.length === 0) {
  const objMatches = rawText.match(/\{[\s\S]*?\"spending_category\"[\s\S]*?\}/g) || [];
  for (const objStr of objMatches) {
    try {
      const parsed = JSON.parse(objStr);
      if (parsed && typeof parsed === 'object') {
        aiArray.push(parsed);
      }
    } catch (e2) {
      try {
        const cleaned = objStr.replace(/,\s*([\}\]])/g, '$1');
        aiArray.push(JSON.parse(cleaned));
      } catch (e3) {}
    }
  }
}

return aiArray.map(item => ({
  json: {
    spending_category: item.spending_category || 'khac',
    target_bank: item.target_bank || 'Chưa xác định',
    target_card: item.target_card || 'Chưa xác định',
    intent: item.intent || 'khac',
    summary: item.summary || 'Khách hàng quan tâm đến dịch vụ thẻ tín dụng.',
    director_action: item.director_action || 'Đề xuất Ban Giám đốc chỉ đạo chuyên viên tư vấn tiếp cận và hỗ trợ kịp thời.'
  }
}));

// Gom toàn bộ các bản ghi insights đã xử lý thành 1 item để gửi bản tin báo cáo Telegram
const allItems = $input.all();
return [{
  json: {
    total_processed: allItems.length,
    timestamp: new Date().toISOString()
  }
}];
